  const gu=GP({xm:6,y0:-1,y1:11,yl:"u (m/s)",s:[{p:[[0,4],[5,4]]}]});
  M("eok",1,"Στο διάγραμμα u–t το διάστημα που διανύει το κινητό στα πρώτα 5 s είναι:",["4 m","20 m","9 m","1,25 m"],1,"Εμβαδόν ορθογωνίου: 4·5 = 20 m.",gu);
  const gp=GP({xm:11,y0:-1,y1:22,yl:"x (m)",s:[{p:[[0,0],[4,20],[8,20],[10,0]]}]});
